-- Objective: Create the persisted song, generated-frame, and sentence audio-content schema used by radio playback.
create table if not exists "public"."songs" (
  "id" bigint generated by default as identity primary key,
  "external_id" text not null unique,
  "title" text not null,
  "artist" text,
  "album" text,
  "audio_path" text not null,
  "duration_seconds" integer,
  "tone" integer not null,
  "language" text default 'en',
  "genre" text,
  "mood" text,
  "tags" jsonb not null default '[]',
  "relationship_tags" jsonb not null default '[]',
  "times_played" integer not null default 0,
  "last_played_at" timestamptz,
  "enabled" boolean not null default true,
  "created_at" timestamptz not null default now(),
  "updated_at" timestamptz not null default now()
);

create index if not exists "songs_tone_idx" on "public"."songs" ("tone");
create index if not exists "songs_enabled_idx" on "public"."songs" ("enabled");
create index if not exists "songs_last_played_at_idx" on "public"."songs" ("last_played_at");

alter table "public"."songs" enable row level security;

create table if not exists "public"."frames" (
  "id" bigint generated by default as identity primary key,
  "external_id" text not null unique,
  "audio_path" text not null,
  "duration_seconds" integer not null,
  "transcript" text,
  "next_frame_id" bigint references "public"."frames"("id"),
  "metadata" jsonb not null default '{}',
  "created_at" timestamptz not null default now()
);

create index if not exists "frames_next_frame_id_idx" on "public"."frames" ("next_frame_id");
create index if not exists "frames_created_at_idx" on "public"."frames" ("created_at");

alter table "public"."frames" enable row level security;

create table if not exists "public"."sentences" (
  "id" bigint generated by default as identity primary key,
  "external_id" text not null unique,
  "type" text not null,
  "song_id" bigint references "public"."songs"("id"),
  "first_frame_id" bigint not null references "public"."frames"("id"),
  "duration_seconds" integer not null,
  "transcript" text,
  "tone" integer,
  "metadata" jsonb not null default '{}',
  "created_at" timestamptz not null default now()
);

create index if not exists "sentences_type_idx" on "public"."sentences" ("type");
create index if not exists "sentences_song_id_idx" on "public"."sentences" ("song_id");
create index if not exists "sentences_first_frame_id_idx" on "public"."sentences" ("first_frame_id");
create index if not exists "sentences_tone_idx" on "public"."sentences" ("tone");
create index if not exists "sentences_created_at_idx" on "public"."sentences" ("created_at");

alter table "public"."sentences" enable row level security;
